<?php $v=$form?:[];$edit=!empty($form);$defaults=$newTradeDefaults??[];$selectedAccount=(int)($v['account_id']??$defaults['account_id']??0);$selectedSystem=(int)($v['trading_system_id']??$defaults['trading_system_id']??0);$selectedStrategy=(int)($v['strategy_id']??0);$selectedAsset=(int)($v['asset_id']??0);$selectedSession=(int)($v['trading_session_id']??0);if(!$selectedSystem&&$selectedAccount){foreach($accounts as $a){if((int)$a['id']===$selectedAccount){$selectedSystem=(int)($a['default_system_id']??0);break;}}}$risk=$editRisk??null;$initialRisk=(float)($risk['ideal_risk']??0);$initialBalance=(float)($risk['balance_before']??0);?>
<form method="post" id="trade-form" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><?php if($edit):?><input type="hidden" name="id" value="<?=e($v['id'])?>"><?php endif;?>
<div class="form-section"><div class="form-section-title">Trade Setup</div><div class="grid">
<p><label>Account</label><select name="account_id" required><?php foreach($accounts as $a):?><option value="<?=e($a['id'])?>" data-default-system="<?=e($a['default_system_id']??'')?>" data-ideal-risk="<?=e($a['ideal_risk']??0)?>" data-balance="<?=e($a['initial_balance']??0)?>" <?=$selectedAccount===(int)$a['id']?'selected':''?>><?=e($a['name'])?> (<?=e($a['currency'])?>)</option><?php endforeach;?></select></p>
<p><label>Trading system</label><select name="trading_system_id"><option value="">None</option><?php foreach($systems as $s):?><option value="<?=e($s['id'])?>" data-ideal-risk="<?=e($s['ideal_risk'])?>" data-risk-tolerance="<?=e($s['risk_tolerance'])?>" <?=$selectedSystem===(int)$s['id']?'selected':''?>><?=e($s['name'])?> — risk <?=number_format((float)$s['ideal_risk'],2)?></option><?php endforeach;?></select></p>
<p><label>Strategy</label><select name="strategy_id"><option value="">None</option><?php foreach($strategies as $s):?><option value="<?=e($s['id'])?>" data-system="<?=e($s['trading_system_id'])?>" <?=$selectedStrategy===(int)$s['id']?'selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></p>
<p><label>Asset</label><select name="asset_id"><option value="">None</option><?php foreach($assets as $a):?><option value="<?=e($a['id'])?>" data-symbol="<?=e($a['symbol'])?>" data-configuration="<?=e(json_encode($a['configuration']??null))?>" <?=$selectedAsset===(int)$a['id']?'selected':''?>><?=e($a['symbol'])?> — <?=e($a['name'])?></option><?php endforeach;?></select></p>
<p><label>Session</label><select name="trading_session_id"><option value="">None</option><?php foreach($sessions as $s):?><option value="<?=e($s['id'])?>" <?=$selectedSession===(int)$s['id']?'selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></p>
<p><label>Ticket</label><input name="ticket" value="<?=e($v['ticket']??'')?>"></p><p><label>Symbol</label><input id="trade-symbol" name="symbol" value="<?=e($v['symbol']??'')?>" required></p><p><label>Timeframe</label><select name="timeframe"><option value="">Not set</option><?php foreach(['1m','5m','15m','30m','1h','4h','1d','1w'] as $tf):?><option value="<?=$tf?>" <?=($v['timeframe']??'')===$tf?'selected':''?>><?=$tf?></option><?php endforeach;?></select></p>
<p><label>Side</label><select name="side"><option value="long" <?=($v['side']??'long')==='long'?'selected':''?>>Long</option><option value="short" <?=($v['side']??'')==='short'?'selected':''?>>Short</option></select></p><p><label>Status</label><select name="status"><option value="closed" <?=($v['status']??'closed')==='closed'?'selected':''?>>Closed</option><option value="open" <?=($v['status']??'')==='open'?'selected':''?>>Open</option></select></p>
</div></div>
<div class="form-section"><div class="form-section-title">Timing &amp; Execution</div><div class="grid">
<p><label>Opening time</label><input type="datetime-local" name="opened_at" value="<?=isset($v['opened_at'])?e(date('Y-m-d\\TH:i',strtotime($v['opened_at']))):''?>" required></p><p><label>Closing time</label><input type="datetime-local" name="closed_at" value="<?=!empty($v['closed_at'])?e(date('Y-m-d\\TH:i',strtotime($v['closed_at']))):''?>"></p>
<p><label>Quantity</label><input id="trade-quantity" type="number" step=".00000001" min=".00000001" name="quantity" value="<?=e($v['quantity']??'')?>" required></p><p><label>Entry price</label><input id="trade-entry" type="number" step=".0000000001" min="0" name="entry_price" value="<?=e($v['entry_price']??'')?>" required></p>
<p><label>Stop loss</label><input id="trade-stop" type="number" step=".0000000001" min="0" name="stop_loss" value="<?=e($v['stop_loss']??'')?>"></p><p><label>Take profit</label><input type="number" step=".0000000001" min="0" name="take_profit" value="<?=e($v['take_profit']??'')?>"></p><p><label>Exit price</label><input id="trade-exit" type="number" step=".0000000001" min="0" name="exit_price" value="<?=e($v['exit_price']??'')?>"></p><p><label>Fees</label><input id="trade-fees" type="number" step=".00000001" min="0" name="fees" value="<?=e($v['fees']??'0')?>"></p>
</div></div>
<div class="form-section"><div class="form-section-title">Trade Quality</div><div class="grid"><p><label>Grade</label><select name="grade"><option value="">Not graded</option><?php foreach(\App\Services\FeatureParityService::GRADES as $g):?><option value="<?=e($g)?>" <?=($v['grade']??'')===$g?'selected':''?>><?=e($g)?> (<?=number_format(\App\Services\FeatureParityService::GRADE_MULTIPLIERS[$g],2)?>x risk)</option><?php endforeach;?></select></p><p><label>Screenshot</label><input type="file" name="screenshot" accept="image/png,image/jpeg"><?php if(!empty($v['screenshot_path'])):?><span class="field-help">Current screenshot will be kept unless a new image is selected.</span><?php else:?><span class="field-help">PNG or JPEG, max 5 MB.</span><?php endif;?></p></div><p><label>Notes</label><textarea name="notes" placeholder="Optional execution notes..."><?=e($v['notes']??'')?></textarea></p></div>
<div class="card" id="risk-card"><div class="form-section-title">Live Risk Calculation</div><div class="grid"><p>Base ideal risk: <strong id="risk-base"><?=number_format($risk['base_ideal_risk']??$initialRisk,2)?></strong></p><p>Grade-adjusted ideal risk: <strong id="risk-ideal"><?=number_format($initialRisk,2)?></strong></p><p>Grade multiplier: <strong id="risk-grade"><?=number_format($risk['grade_multiplier']??1,2)?>x</strong></p><p>Risk amount: <strong id="risk-amount">—</strong></p><p>Actual risk incl. fees: <strong id="risk-actual"><?=$risk&&$risk['actual_risk']!==null?number_format($risk['actual_risk'],2):'—'?></strong></p><p>Risk %: <strong id="risk-percent"><?=$risk&&$risk['risk_percent']!==null?number_format($risk['risk_percent'],2).'%':'—'?></strong></p><p>Position size: <strong id="risk-position"><?=$risk&&$risk['position_size']!==null?number_format($risk['position_size'],4):'—'?></strong></p><p>Expected R: <strong id="risk-expected"><?=$risk&&$risk['expected_r']!==null?number_format($risk['expected_r'],2).'R':'—'?></strong></p><p>R multiple: <strong id="risk-multiple"><?=$risk&&$risk['r_multiple']!==null?number_format($risk['r_multiple'],2).'R':'—'?></strong></p><p>Risk deviation: <strong id="risk-deviation"><?=$risk&&$risk['risk_deviation']!==null?number_format($risk['risk_deviation'],2).'%':'—'?></strong></p><p>Balance after: <strong id="risk-balance"><?=number_format($risk['balance_after']??$initialBalance,2)?></strong></p></div><p><button type="button" class="secondary" id="ideal-stop">Calculate Ideal Stop Loss</button> <span id="risk-help"></span></p></div>
<div class="actions"><button><?=$edit?'Save changes':'Add trade'?></button><?php if($edit):?><a class="secondary-link" href="/trades">Cancel</a><?php endif;?></div></form>
<script nonce="<?=e(csp_nonce())?>">(function(){const form=document.getElementById('trade-form'),account=form.querySelector('[name="account_id"]'),system=form.querySelector('[name="trading_system_id"]'),strategy=form.querySelector('[name="strategy_id"]'),asset=form.querySelector('[name="asset_id"]'),symbol=document.getElementById('trade-symbol'),quantity=document.getElementById('trade-quantity'),entry=document.getElementById('trade-entry'),stop=document.getElementById('trade-stop'),exit=document.getElementById('trade-exit'),fees=document.getElementById('trade-fees'),side=form.querySelector('[name="side"]'),grade=form.querySelector('[name="grade"]');const el={base:document.getElementById('risk-base'),ideal:document.getElementById('risk-ideal'),gm:document.getElementById('risk-grade'),amount:document.getElementById('risk-amount'),actual:document.getElementById('risk-actual'),percent:document.getElementById('risk-percent'),position:document.getElementById('risk-position'),expected:document.getElementById('risk-expected'),multiple:document.getElementById('risk-multiple'),deviation:document.getElementById('risk-deviation'),balance:document.getElementById('risk-balance'),help:document.getElementById('risk-help')};const multipliers=<?=json_encode(\App\Services\FeatureParityService::GRADE_MULTIPLIERS)?>;function num(v){const n=parseFloat(v);return Number.isFinite(n)?n:null}function fmt(n,d){return Number.isFinite(n)?n.toLocaleString(undefined,{minimumFractionDigits:d,maximumFractionDigits:d}):'—'}function selectedBase(){const so=system.selectedOptions[0];if(system.value&&so)return num(so.dataset.idealRisk)||0;const ao=account.selectedOptions[0];return ao?num(ao.dataset.idealRisk)||0:0}function config(){const o=asset.selectedOptions[0];if(!o||!o.value)return{contract_size:1,point_value:1};try{const c=JSON.parse(o.dataset.configuration||'null');return c&&typeof c==='object'?c:{contract_size:1,point_value:1}}catch(e){return{contract_size:1,point_value:1}}}function filterStrategies(){[...strategy.options].forEach(o=>{if(o.value)o.hidden=system.value!==''&&o.dataset.system!==system.value});if(strategy.selectedOptions[0]&&strategy.selectedOptions[0].hidden)strategy.value=''}function recalc(){const q=num(quantity.value),en=num(entry.value),sl=num(stop.value),ex=num(exit.value),fee=num(fees.value)||0,base=selectedBase(),gm=multipliers[grade.value]||1,ideal=base*gm,balance=num(account.selectedOptions[0]?.dataset.balance)||0,c=config(),mult=Math.max(0,(num(c.contract_size)||1)*(num(c.point_value)||1));el.base.textContent=fmt(base,2);el.ideal.textContent=fmt(ideal,2);el.gm.textContent=fmt(gm,2)+'x';const riskPerUnit=en!==null&&sl!==null?Math.abs(en-sl)*mult:null,riskAmount=riskPerUnit!==null&&q!==null?riskPerUnit*q:null,actual=riskAmount!==null?riskAmount+fee:null,riskPct=actual!==null&&balance>0?actual/balance*100:null,position=ideal>0&&riskPerUnit>0?Math.max(0,(ideal-fee)/riskPerUnit):null;let pnl=null;if(en!==null&&ex!==null&&q!==null)pnl=((side.value==='short'?en-ex:ex-en)*q)-fee;const expected=pnl!==null&&ideal>0?pnl/ideal:null,multiple=pnl!==null&&riskAmount>0?pnl/riskAmount:null,deviation=actual!==null&&ideal>0?(actual-ideal)/ideal*100:null;el.amount.textContent=fmt(riskAmount,2);el.actual.textContent=fmt(actual,2);el.percent.textContent=riskPct===null?'—':fmt(riskPct,2)+'%';el.position.textContent=fmt(position,4);el.expected.textContent=expected===null?'—':fmt(expected,2)+'R';el.multiple.textContent=multiple===null?'—':fmt(multiple,2)+'R';el.deviation.textContent=deviation===null?'—':fmt(deviation,2)+'%';el.balance.textContent=fmt(pnl===null?balance:balance+pnl,2);el.help.textContent=ideal<=0?'Configure Ideal Risk first.':(sl===null?'Enter a stop loss or use Calculate Ideal Stop Loss.':'')}function idealStop(){const q=num(quantity.value),en=num(entry.value),fee=num(fees.value)||0,base=selectedBase(),gm=multipliers[grade.value]||1,c=config(),mult=Math.max(0,(num(c.contract_size)||1)*(num(c.point_value)||1)),ideal=base*gm;if(en===null||q===null||q<=0||ideal<=0||mult<=0)return;const risk=Math.max(0,ideal-fee)/(q*mult);stop.value=(side.value==='short'?en+risk:en-risk).toFixed(10);recalc()}account.addEventListener('change',function(){if(!system.value){const o=account.selectedOptions[0];if(o&&o.dataset.defaultSystem)system.value=o.dataset.defaultSystem}filterStrategies();recalc()});system.addEventListener('change',function(){filterStrategies();recalc()});strategy.addEventListener('change',recalc);asset.addEventListener('change',function(){const o=asset.selectedOptions[0];if(o&&o.dataset.symbol&&!symbol.value)symbol.value=o.dataset.symbol;recalc()});[quantity,entry,stop,exit,fees,symbol].forEach(x=>x.addEventListener('input',recalc));side.addEventListener('change',recalc);grade.addEventListener('change',recalc);document.getElementById('ideal-stop').addEventListener('click',idealStop);filterStrategies();recalc()})();</script>